import requests
from PIL import Image
import io

def task_func(url):
    try:
        response = requests.get(url, timeout=5, allow_redirects=False)
    except requests.exceptions.RequestException as e:
        raise ValueError("The URL is invalid or could not be reached within 5 seconds.") from e

    if not (200 <= response.status_code < 300):
        raise ValueError(f"Unexpected HTTP status code: {response.status_code}")

    try:
        with Image.open(io.BytesIO(response.content)) as img:
            img.load()
            return img.copy()
    except (OSError, ValueError) as e:
        raise ValueError("The fetched content is not a valid image.") from e
